using Datapoint.Apiary.Certificates.Dns;

namespace Datapoint.Apiary.Certificates.Tests.Dns;

public sealed class DnsTsigTests
{
    private const string Secret = "c2VjcmV0LWZvci10ZXN0cy0zMi1ieXRlcy1sb25nLi4=";

    [Theory]
    [InlineData(
        DnsTsig.HmacSha256,
        "7f2a28000001000000010000076578616d706c65047465737400000600010f5f61636d652d6368616c6c656e67650473686f70c00c001000010000003c000403616263",
        "",
        1793981185)]
    [InlineData(
        DnsTsig.HmacSha512,
        "8aae28000001000000010000076578616d706c65047465737400000600010f5f61636d652d6368616c6c656e67650473686f70c00c001000fe00000000002c2b4c6f71586359563871354f4e624a5178626d52375343544e6f337469415844666f77796a78416a45755830",
        "",
        1793981206)]
    public void Signs_an_update_as_BIND_s_nsupdate_does(string algorithm, string message, string signedByNsupdate, long signedAt)
    {
        var key = new DnsTsigKey("apiary-acme", algorithm, Convert.FromBase64String(Secret));

        var signed = DnsTsig.Sign(Convert.FromHexString(message), key, DateTimeOffset.FromUnixTimeSeconds(signedAt));

        Assert.Equal(signedByNsupdate, Convert.ToHexStringLower(signed));
    }
}
